/**
 * Mini Futabasaurus (Tipo Agua) — Versión Chibi / Cría compañera de plesiosaurio.
 * Basado en el arte oficial de Dinosaur King:
 *   assets/dinos/arte/agua/futabasaurus_der.webp
 *
 * Características anatómicas del Futabasaurus (Plesiosaurio Elasmosáurido Japonés):
 *   - Cuerpo hidrodinámico fusiforme, robusto, compacto y continuo.
 *   - Cuello proporcionado, más corto y visiblemente más grueso y musculoso que el de Elasmosaurus,
 *     con un porte erguido y ágil en arco suave y orgánico hacia la cabeza.
 *   - 4 aletas natatorias en forma de hidroalas marinas estilizadas y aerodinámicas
 *     (puntas redondeadas y perfil alar fino), con cúpulas semiesféricas internas dentro del cuerpo.
 *   - Cabeza estilizada con mandíbula inferior articulada para rugir y cazar.
 *   - Dientes cónicos en aguja entrelazados de marfil y fosas nasales hidrodinámicas.
 *   - Ojos grandes anime tipo agua con iris azul zafiro/turquesa y destellos brillantes.
 *   - Proyección lateral de la textura oficial: lomo índigo/pizarra azulado con destellos iridiscentes,
 *     garganta y vientre inferior continuo en tono crema hielo celeste.
 *   - Esqueleto y 3 animaciones fluidas (Reposo flotante, Caminar / Nadar marino, Rugir / Embestida).
 */
registrarMalla({
  id: "mini_futabasaurus",
  categoria: "mini dino",
  nombre: "Mini Futabasaurus (Agua)",
  icono: "🌊",
  origen: "assets/dinos/arte/agua/futabasaurus_der.webp",

  construir(M) {
    const g = new THREE.Group();
    const LADOS = [-1, 1];
    const L = (s) => (s > 0 ? "I" : "D");
    const V = (x, y, z) => new THREE.Vector3(x, y, z);
    const grad = Math.PI / 180;
    const cr = (p0, p1, p2, p3, t) => 0.5 * ((2 * p1) + (-p0 + p2) * t
      + (2 * p0 - 5 * p1 + 4 * p2 - p3) * t * t + (-p0 + 3 * p1 - 3 * p2 + p3) * t * t * t);

    const ALETA_DEL_X = 0.17;
    const ALETA_TRAS_X = 0.16;

    // ---------------- UTILIDADES GEOMÉTRICAS ----------------
    const suave = (a, b, x) => {
      const t = Math.max(0, Math.min(1, (x - a) / (b - a)));
      return t * t * (3 - 2 * t);
    };

    function rejilla(pos, cols, rows, nombre) {
      const idx = [];
      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
          const a = r * (cols + 1) + c;
          const b = a + cols + 1;
          idx.push(a, b, a + 1, b, b + 1, a + 1);
        }
      }
      const geo = new THREE.BufferGeometry();
      geo.setAttribute("position", new THREE.Float32BufferAttribute(pos, 3));
      geo.setIndex(idx);
      geo.computeVertexNormals();
      return M.pieza(geo, nombre, cols, rows);
    }

    // Pieza cónica/alargada cerrada (dientes)
    function punta(camino, radio, nombre, segL = 12, segR = 8) {
      const curva = M.curva(camino);
      const geo = new THREE.TubeGeometry(curva, M.seg(segL, 6), 1, M.seg(segR, 6), false);
      const pos = geo.attributes.position;
      const P = new THREE.Vector3();
      const sL = M.seg(segL, 6);
      const sR = M.seg(segR, 6);

      for (let i = 0; i <= sL; i++) {
        const t = i / sL;
        curva.getPointAt(t, P);
        const r = radio * Math.pow(Math.max(0, 1 - t), 0.78);
        for (let j = 0; j <= sR; j++) {
          const k = i * (sR + 1) + j;
          pos.setXYZ(k,
            P.x + (pos.getX(k) - P.x) * r,
            P.y + (pos.getY(k) - P.y) * r,
            P.z + (pos.getZ(k) - P.z) * r
          );
        }
      }
      return M.coserNormales(M.pieza(geo, nombre, sR, sL));
    }

    // Bloque redondeado cerrado para lengua, párpados y detalles
    function bloque(cx, cy, cz, rx, ry, rz, redond = 1, nombre = "Detalle", sW = 16, sH = 12) {
      const geo = new THREE.SphereGeometry(1, M.seg(sW, 8), M.seg(sH, 6));
      const pos = geo.attributes.position;
      for (let i = 0; i < pos.count; i++) {
        let x = pos.getX(i);
        let y = pos.getY(i);
        let z = pos.getZ(i);
        if (redond < 0.999) {
          const fx = Math.pow(Math.abs(x), redond);
          const fy = Math.pow(Math.abs(y), redond);
          const fz = Math.pow(Math.abs(z), redond);
          x = Math.sign(x) * fx;
          y = Math.sign(y) * fy;
          z = Math.sign(z) * fz;
        }
        pos.setXYZ(i, cx + x * rx, cy + y * ry, cz + z * rz);
      }
      geo.computeVertexNormals();
      return M.pieza(geo, nombre, sW, sH);
    }

    // Almendra ocular cerrada
    function almendra(rx, ry, rz, nombre = "Almendra") {
      const sW = M.seg(16, 8);
      const sH = M.seg(12, 6);
      const geo = new THREE.SphereGeometry(1, sW, sH);
      const pos = geo.attributes.position;
      for (let i = 0; i < pos.count; i++) {
        let x = pos.getX(i);
        let y = pos.getY(i);
        let z = pos.getZ(i);
        const f = 1 - 0.28 * Math.pow(Math.abs(x), 1.8);
        pos.setXYZ(i, x * rx, y * ry * f, z * rz);
      }
      geo.computeVertexNormals();
      return M.pieza(geo, nombre, sW, sH);
    }

    // ---------------- 1. CUERPO CONTINUO FUSIFORME 100% CERRADO ----------------
    // Eje longitudinal hidrodinámico con curvatura suave, continua y orgánica sin pliegues bruscos:
    // [z, y, semiancho, altoHaciaArriba, altoHaciaAbajo, forma]
    const EJE = [
      [-0.62, 0.480, 0.000, 0.000, 0.000, 2.0],  // Punta cola timón cerrada (elevada)
      [-0.52, 0.450, 0.040, 0.042, 0.038, 2.0],  // Cola posterior
      [-0.40, 0.420, 0.075, 0.078, 0.072, 2.1],  // Cola media
      [-0.28, 0.380, 0.125, 0.125, 0.115, 2.2],  // Base de la cola
      [-0.16, 0.350, 0.180, 0.155, 0.145, 2.4],  // Cadera y aletas traseras
      [-0.04, 0.340, 0.205, 0.170, 0.160, 2.5],  // Torso medio hidrodinámico
      [ 0.08, 0.350, 0.185, 0.160, 0.150, 2.4],  // Pecho y aletas delanteras
      [ 0.18, 0.400, 0.145, 0.140, 0.130, 2.3],  // Base del cuello (musculosa y suave)
      [ 0.27, 0.500, 0.110, 0.115, 0.105, 2.2],  // Cuello inferior en arco gradual
      [ 0.36, 0.630, 0.082, 0.090, 0.082, 2.2],  // Cuello medio
      [ 0.44, 0.720, 0.070, 0.078, 0.070, 2.2],  // Cuello alto / nuca
      [ 0.52, 0.720, 0.068, 0.068, 0.058, 2.3],  // Cráneo chibi
      [ 0.58, 0.710, 0.045, 0.045, 0.038, 2.2],  // Hocico medio
      [ 0.61, 0.700, 0.025, 0.025, 0.020, 2.1],  // Punta del hocico
      [ 0.62, 0.700, 0.000, 0.000, 0.000, 2.0]   // Cierre hermético en domo redondeado
    ];

    const ejeCurva = new THREE.CatmullRomCurve3(EJE.map(([z, y]) => V(0, y, z)), false, "centripetal");
    ejeCurva.arcLengthDivisions = 1600;
    const LARGO = ejeCurva.getLength();

    function seccion(u) {
      const f = ejeCurva.getUtoTmapping(u) * (EJE.length - 1);
      const i = Math.min(EJE.length - 2, Math.floor(f));
      const t = f - i;
      const a = EJE[Math.max(0, i - 1)];
      const b = EJE[i];
      const c = EJE[i + 1];
      const d = EJE[Math.min(EJE.length - 1, i + 2)];
      return [2, 3, 4, 5].map((j) => Math.max(0, cr(a[j], b[j], c[j], d[j], t)));
    }

    const X = V(1, 0, 0);
    function marcoEje(u) {
      const P = ejeCurva.getPointAt(u);
      const T = ejeCurva.getTangentAt(u);
      // Suavizamos el ángulo de inclinación en Y-Z para una transición 100% continua y orgánica:
      const ang = Math.atan2(T.y, T.z);
      const angSuave = ang * 0.28;
      const U = V(0, Math.cos(angSuave), -Math.sin(angSuave));
      return { P, T, U };
    }

    function uCercano(p, desde = 0, hasta = 1) {
      let mejor = desde;
      let dMin = Infinity;
      for (let k = 0; k <= 400; k++) {
        const u = desde + (hasta - desde) * (k / 400);
        const d = ejeCurva.getPointAt(u).distanceToSquared(p);
        if (d < dMin) { dMin = d; mejor = u; }
      }
      return mejor;
    }

    // Malla principal del cuerpo fusiforme
    const COLS = M.seg(96, 28);
    const FILAS = M.seg(440, 80);
    const cuerpo = (() => {
      const pos = [];
      for (let r = 0; r <= FILAS; r++) {
        const u = r / FILAS;
        const { P, U } = marcoEje(u);
        const [w, hA, hB, p] = seccion(u);
        const ex = 2 / p;

        for (let c = 0; c <= COLS; c++) {
          const fi = Math.PI + (c / COLS) * Math.PI * 2;
          const s = Math.sin(fi);
          const co = Math.cos(fi);

          const lx = w * Math.sign(s) * Math.pow(Math.abs(s), ex);
          const ly = (co >= 0 ? hA : hB) * Math.sign(co) * Math.pow(Math.abs(co), ex);
          const pto = P.clone().addScaledVector(X, lx).addScaledVector(U, ly);
          pos.push(pto.x, pto.y, pto.z);
        }
      }
      return M.coserNormales(rejilla(pos, COLS, FILAS, "CuerpoFutabasaurus"));
    })();

    // ---------------- 2. ESQUELETO Y RIGGING ----------------
    const HUESOS = [
      ["Raiz", null, 0, 0, 0],
      ["Cadera", "Raiz", 0, 0.350, -0.16],
      ["Pecho", "Cadera", 0, 0.350, 0.08],
      // 4 vértebras de cuello robusto:
      ["Cuello1", "Pecho", 0, 0.400, 0.18],
      ["Cuello2", "Cuello1", 0, 0.500, 0.27],
      ["Cuello3", "Cuello2", 0, 0.630, 0.36],
      ["Cuello4", "Cuello3", 0, 0.720, 0.44],
      ["Cabeza", "Cuello4", 0, 0.720, 0.52],
      ["Mandibula", "Cabeza", 0, 0.680, 0.50],
      // Cola:
      ["Cola1", "Cadera", 0, 0.380, -0.28],
      ["Cola2", "Cola1", 0, 0.420, -0.40],
      ["Cola3", "Cola2", 0, 0.450, -0.52],
      // 4 aletas natatorias independientes con dos huesos cada una (raíz y pala):
      ...LADOS.flatMap((s) => [
        ["AletaDel" + L(s), "Pecho", s * ALETA_DEL_X, 0.33, 0.06],
        ["AletaPuntaDel" + L(s), "AletaDel" + L(s), s * (ALETA_DEL_X + 0.16), 0.20, -0.05],
        ["AletaTras" + L(s), "Cadera", s * ALETA_TRAS_X, 0.33, -0.18],
        ["AletaPuntaTras" + L(s), "AletaTras" + L(s), s * (ALETA_TRAS_X + 0.14), 0.21, -0.29]
      ])
    ];

    const hueso = {};
    HUESOS.forEach(([nombre, padre, x, y, z]) => {
      const b = new THREE.Bone();
      b.name = "Hueso" + nombre;
      b.userData.reposo = V(x, y, z);
      const p = padre ? hueso[padre] : null;
      b.position.set(x, y, z).sub(p ? p.userData.reposo : V(0, 0, 0));
      (p || g).add(b);
      hueso[nombre] = b;
    });
    g.updateMatrixWorld(true);

    const colgar = (nombre, obj) => {
      const h = typeof nombre === "string" ? hueso[nombre] : nombre;
      if (!h || !obj) return obj;
      h.attach(obj);
      return obj;
    };

    // Tramos de influencia de piel a lo largo del cuerpo fusiforme
    const uCola3 = uCercano(hueso.Cola3.userData.reposo, 0, 0.25);
    const uCola2 = uCercano(hueso.Cola2.userData.reposo, 0.10, 0.35);
    const uCola1 = uCercano(hueso.Cola1.userData.reposo, 0.20, 0.45);
    const uCad = uCercano(hueso.Cadera.userData.reposo, 0.30, 0.55);
    const uPec = uCercano(hueso.Pecho.userData.reposo, 0.45, 0.65);
    const uC1 = uCercano(hueso.Cuello1.userData.reposo, 0.55, 0.72);
    const uC2 = uCercano(hueso.Cuello2.userData.reposo, 0.65, 0.80);
    const uC3 = uCercano(hueso.Cuello3.userData.reposo, 0.72, 0.88);
    const uC4 = uCercano(hueso.Cuello4.userData.reposo, 0.80, 0.94);
    const uCab = uCercano(hueso.Cabeza.userData.reposo, 0.88, 1.00);

    const TRAMOS = [
      [0, "Cola3"],
      [uCola3, "Cola2"],
      [uCola2, "Cola1"],
      [uCola1, "Cadera"],
      [uCad, "Cadera"],
      [uPec, "Pecho"],
      [uC1, "Cuello1"],
      [uC2, "Cuello2"],
      [uC3, "Cuello3"],
      [uC4, "Cuello4"],
      [uCab, "Cabeza"]
    ];

    const MEZCLA = 0.20 / LARGO;
    function pesosTramos(u, tramos, mezcla) {
      let k = 0;
      while (k + 1 < tramos.length && u >= tramos[k + 1][0]) k++;
      const res = [[hueso[tramos[k][1]], 1]];
      if (k + 1 < tramos.length) {
        const w = suave(-mezcla, mezcla, u - tramos[k + 1][0]);
        if (w > 0) { res[0][1] = 1 - w; res.push([hueso[tramos[k + 1][1]], w]); }
      }
      if (k > 0) {
        const w = 1 - suave(-mezcla, mezcla, u - tramos[k][0]);
        if (w > 0) { res[0][1] *= 1 - w; res.push([hueso[tramos[k - 1][1]], w]); }
      }
      return res;
    }

    g.add(cuerpo);
    M.pielConHuesos(cuerpo, g, (i) => pesosTramos(Math.floor(i / (COLS + 1)) / FILAS, TRAMOS, MEZCLA));

    // ---------------- 3. ALETAS NATATORIAS HIDRODINÁMICAS (ALAS MARINAS) ----------------
    function aletaHidrodinamica(s, camino, radiosW, radiosH, huesosAleta, nombre) {
      const curva = M.curva(camino);
      const tSeg = M.seg(24, 10);
      const rSeg = M.seg(24, 10);
      const geo = new THREE.TubeGeometry(curva, tSeg, 1, rSeg, false);
      const pos = geo.attributes.position;
      const P = new THREE.Vector3();

      for (let i = 0; i <= tSeg; i++) {
        const t = i / tSeg;
        curva.getPointAt(t, P);
        let rw = M.interp(radiosW, t);
        let rh = M.interp(radiosH, t);

        // Cúpula semiesférica interna de cierre en la raíz dentro del cuerpo
        if (t < 0.20) {
          const cap = Math.sqrt(Math.max(0, 1 - Math.pow(1 - t / 0.20, 2)));
          rw *= cap;
          rh *= cap;
        }
        // Cierre cónico suave en el extremo de la pala
        if (t > 0.85) {
          const tap = Math.sqrt(Math.max(0, 1 - Math.pow((t - 0.85) / 0.15, 2)));
          rw *= tap;
          rh *= tap;
        }

        for (let j = 0; j <= rSeg; j++) {
          const k = i * (rSeg + 1) + j;
          // Perfil elíptico hidrodinámico: pala ancha en el plano horizontal y fina en espesor vertical
          const lx = (pos.getX(k) - P.x) * rw;
          const ly = (pos.getY(k) - P.y) * rh;
          const lz = (pos.getZ(k) - P.z) * rw * 0.85;

          pos.setXYZ(k, P.x + lx, P.y + ly, P.z + lz);
        }
      }

      const malla = M.coserNormales(M.pieza(geo, nombre, rSeg, tSeg));
      g.add(malla);

      const tramos = [
        [0, huesosAleta[0]],
        [0.55, huesosAleta[1]]
      ];
      M.pielConHuesos(malla, g, (i) => pesosTramos(Math.floor(i / (rSeg + 1)) / tSeg, tramos, 0.18));
      return malla;
    }

    // Aletas pectorales (delanteras) amplias y aerodinámicas
    LADOS.forEach((s) => {
      const xDel = s * ALETA_DEL_X;
      aletaHidrodinamica(s,
        [
          [s * (ALETA_DEL_X - 0.05), 0.35, 0.08],
          [xDel, 0.33, 0.06],
          [s * (ALETA_DEL_X + 0.12), 0.24, -0.01],
          [s * (ALETA_DEL_X + 0.24), 0.15, -0.09],
          [s * (ALETA_DEL_X + 0.33), 0.07, -0.17]
        ],
        [[0, 0.060], [0.30, 0.075], [0.65, 0.065], [1, 0.030]],
        [[0, 0.040], [0.30, 0.024], [0.65, 0.015], [1, 0.006]],
        ["AletaDel" + L(s), "AletaPuntaDel" + L(s)], "AletaPectoralFutaba");

      // Aletas pélvicas (traseras) timón de empuje
      const xTras = s * ALETA_TRAS_X;
      aletaHidrodinamica(s,
        [
          [s * (ALETA_TRAS_X - 0.04), 0.35, -0.16],
          [xTras, 0.33, -0.18],
          [s * (ALETA_TRAS_X + 0.10), 0.25, -0.25],
          [s * (ALETA_TRAS_X + 0.20), 0.17, -0.33],
          [s * (ALETA_TRAS_X + 0.28), 0.10, -0.40]
        ],
        [[0, 0.055], [0.30, 0.065], [0.65, 0.055], [1, 0.025]],
        [[0, 0.035], [0.30, 0.020], [0.65, 0.013], [1, 0.005]],
        ["AletaTras" + L(s), "AletaPuntaTras" + L(s)], "AletaPelvicaFutaba");
    });

    // ---------------- 4. MANDÍBULA ARTICULADA, DIENTES EN AGUJA Y OJOS ANIME ----------------
    const MAND_PERFIL = [
      // [z, y, semiancho, alto, forma]
      [0.48, 0.690, 0.065, 0.022, 2.2],  // Comisura trasera articulada
      [0.53, 0.688, 0.058, 0.020, 2.2],  // Parte media de la mandíbula
      [0.57, 0.685, 0.042, 0.018, 2.2],  // Hacia el extremo anterior
      [0.60, 0.682, 0.024, 0.014, 2.1],  // Punta anterior
      [0.61, 0.680, 0.000, 0.000, 2.0]   // Cierre suave hermético
    ];

    const colsMand = M.seg(48, 20);
    const filasMand = M.seg(32, 16);
    const posMand = [];

    for (let r = 0; r <= filasMand; r++) {
      const t = r / filasMand;
      const f = t * (MAND_PERFIL.length - 1);
      const i = Math.min(MAND_PERFIL.length - 2, Math.floor(f));
      const k = f - i;
      const a = MAND_PERFIL[Math.max(0, i - 1)];
      const b = MAND_PERFIL[i];
      const c = MAND_PERFIL[i + 1];
      const d = MAND_PERFIL[Math.min(MAND_PERFIL.length - 1, i + 2)];
      const [z, y, w, h, p] = [0, 1, 2, 3, 4].map((j) => cr(a[j], b[j], c[j], d[j], k));
      const ex = 2 / p;

      for (let col = 0; col <= colsMand; col++) {
        const fi = Math.PI + (col / colsMand) * Math.PI * 2;
        const s = Math.sin(fi);
        const co = Math.cos(fi);
        const lx = w * Math.sign(s) * Math.pow(Math.abs(s), ex);
        const ly = h * Math.sign(co) * Math.pow(Math.abs(co), ex);
        posMand.push(lx, y + ly, z);
      }
    }

    colgar("Mandibula", M.coserNormales(rejilla(posMand, colsMand, filasMand, "MandibulaFutaba")));
    colgar("Mandibula", bloque(0, 0.690, 0.54, 0.026, 0.010, 0.050, 0.6, "Lengua"));

    // Dientes cónicos en aguja entrelazados
    LADOS.forEach((s) => {
      // Dientes inferiores
      [0.510, 0.535, 0.560, 0.585, 0.600].forEach((z, idx) => {
        const wTeeth = 0.055 - idx * 0.006;
        const xTeeth = s * wTeeth;
        colgar("Mandibula", punta([[xTeeth, 0.692, z], [xTeeth, 0.704, z + 0.002]], 0.0035, "DienteInferior", 8, 6));
      });

      // Dientes superiores
      [0.522, 0.548, 0.572, 0.592, 0.605].forEach((z, idx) => {
        const wTeeth = 0.058 - idx * 0.006;
        const xTeeth = s * wTeeth;
        colgar("Cabeza", punta([[xTeeth, 0.706, z], [xTeeth, 0.694, z + 0.002]], 0.0038, "DienteSuperior", 8, 6));
      });

      // Labio superior suave
      const labioPuntos = [
        [s * 0.068, 0.710, 0.49],
        [s * 0.060, 0.706, 0.54],
        [s * 0.048, 0.702, 0.58],
        [s * 0.030, 0.698, 0.60],
        [s * 0.005, 0.695, 0.615]
      ];
      colgar("Cabeza", M.tubo(labioPuntos, 0.0055, 0.004, { segLargo: 24, segRadio: 10, nombre: "LabioSuperior" }));
    });

    // Fosas nasales en lo alto del hocico
    LADOS.forEach((s) => {
      colgar("Cabeza", bloque(s * 0.020, 0.732, 0.57, 0.005, 0.004, 0.006, 0.4, "FosaNasal", 10, 8));
    });

    // Ojos anime grandes y expresivos de criatura marina
    LADOS.forEach((s) => {
      const ojoGrupo = new THREE.Group();
      ojoGrupo.position.set(s * 0.060, 0.745, 0.52);
      ojoGrupo.rotation.y = s * 0.38;

      // Córnea blanca
      ojoGrupo.add(almendra(0.042, 0.038, 0.012, "OjoBlanco"));

      // Iris azul zafiro marino / turquesa intenso
      ojoGrupo.add(bloque(s * 0.003, 0, 0.005, 0.030, 0.030, 0.007, 1, "IrisAgua"));

      // Pupila profunda
      ojoGrupo.add(bloque(s * 0.003, -0.001, 0.010, 0.016, 0.018, 0.005, 1, "Pupila"));

      // Brillos especulares
      ojoGrupo.add(bloque(-s * 0.010, 0.012, 0.013, 0.011, 0.011, 0.004, 1, "BrilloOjo"));
      ojoGrupo.add(bloque(s * 0.010, -0.009, 0.012, 0.006, 0.006, 0.003, 1, "BrilloOjoPequeno"));

      // Párpados finos
      ojoGrupo.add(M.tubo([
        [-0.038, 0.005, 0.005],
        [0, 0.036, 0.010],
        [0.038, 0.005, 0.005]
      ], 0.0042, 0.0032, { segLargo: 10, segRadio: 8, nombre: "ParpadoSuperior" }));

      ojoGrupo.add(M.tubo([
        [-0.034, -0.005, 0.005],
        [0, -0.033, 0.008],
        [0.034, -0.005, 0.005]
      ], 0.0036, 0.0028, { segLargo: 10, segRadio: 8, nombre: "ParpadoInferior" }));

      colgar("Cabeza", ojoGrupo);
    });

    // ---------------- 5. PINTURA: PROYECCIÓN Y COLORES DE FUTABASAURUS_DER.WEBP ----------------
    const TEXTURA = this.textura;
    const proyectar = M.proyeccion(TEXTURA, 1.15);

    // Paleta de colores vibrante oficial de Futabasaurus
    const C_BASE_INDIGO = new THREE.Color(0x3e526c);
    const C_LOMO_LAVANDA = new THREE.Color(0x6e6884);
    const C_CREMA_VIENTRE = new THREE.Color(0xdceef7);
    const C_LENGUA = new THREE.Color(0xd97575);
    const MARFIL = new THREE.Color(0xfbf6ea);
    const cColor = new THREE.Color();

    // Pintar cuerpo cerrado con proyección lateral y vientre crema hielo continuo
    M.pintar(cuerpo, (i, p) => {
      proyectar(p.z, p.y, cColor);

      // Si cae en zona transparente o negra del fondo, salvaguarda con color base índigo
      if (cColor.r < 0.12 && cColor.g < 0.14 && cColor.b < 0.16) {
        cColor.copy(C_BASE_INDIGO);
      }

      // Evitar que zonas oscuras de la textura queden demasiado negras:
      cColor.r = Math.max(cColor.r, 0.18);
      cColor.g = Math.max(cColor.g, 0.22);
      cColor.b = Math.max(cColor.b, 0.28);

      const u = Math.floor(i / (COLS + 1)) / FILAS;
      const cIdx = i % (COLS + 1);
      const fi = Math.PI + (cIdx / COLS) * Math.PI * 2;
      const co = Math.cos(fi);

      // Pecho, garganta y vientre inferior en suave tono hielo celeste/crema continuo
      if (co < 0.25 && p.y < 0.62 && u > 0.06 && u < 0.94) {
        const factorVientre = Math.pow((0.25 - co) / 1.25, 1.2) * (1 - Math.min(1, Math.abs(p.x) / 0.18));
        cColor.lerp(C_CREMA_VIENTRE, Math.min(1, factorVientre * 0.92));
      }

      return cColor;
    }, g);

    // Pintar piezas secundarias
    const COLOR_PIEZAS = {
      mandibula: 0x475a72,
      labio: 0x2e3c4e,
      fosaNasal: 0x1d2733,
      parpado: 0x3d4f66,
      iris: 0x06b6d4,
      pupila: 0x0f172a,
      brillo: 0xffffff,
      ojoBlanco: 0xfefcf9
    };

    const piezas = [];
    g.traverse((o) => { if (o.isMesh && o !== cuerpo) piezas.push(o); });

    piezas.forEach((o) => {
      if (/^Diente/.test(o.name)) return M.pintar(o, () => MARFIL, g);
      if (o.name === "Lengua") return M.pintar(o, () => C_LENGUA, g);
      if (o.name === "OjoBlanco") return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.ojoBlanco), g);
      if (o.name === "IrisAgua") return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.iris), g);
      if (o.name === "Pupila") return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.pupila), g);
      if (/^BrilloOjo/.test(o.name)) return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.brillo), g);
      if (/^Parpado/.test(o.name)) return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.parpado), g);
      if (o.name === "LabioSuperior") return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.labio), g);
      if (o.name === "FosaNasal") return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.fosaNasal), g);

      // Aletas con proyección lateral y salvaguarda índigo
      if (/^Aleta/.test(o.name)) {
        return M.pintar(o, (i, p) => {
          proyectar(p.z, p.y, cColor);
          if (cColor.r < 0.12 && cColor.g < 0.14 && cColor.b < 0.16) {
            cColor.setHex(0x4a5d76);
          }
          cColor.r = Math.max(cColor.r, 0.18);
          cColor.g = Math.max(cColor.g, 0.22);
          cColor.b = Math.max(cColor.b, 0.28);
          return cColor;
        }, g);
      }

      // Por defecto proyección
      M.pintar(o, (i, p) => {
        proyectar(p.z, p.y, cColor);
        if (cColor.r < 0.12 && cColor.g < 0.14 && cColor.b < 0.16) cColor.copy(C_BASE_INDIGO);
        return cColor;
      }, g);
    });

    // ---------------- 6. ANIMACIONES MARINAS FLUIDAS ----------------
    const q = new THREE.Quaternion();
    const eu = new THREE.Euler();
    function giro(nombre, dur, fn, n = 32) {
      const tiempos = [];
      const valores = [];
      for (let i = 0; i <= n; i++) {
        const [x, y, z] = fn(i / n);
        eu.set(x * grad, y * grad, z * grad);
        q.setFromEuler(eu);
        tiempos.push(i * (dur / n));
        valores.push(q.x, q.y, q.z, q.w);
      }
      return new THREE.QuaternionKeyframeTrack("Hueso" + nombre + ".quaternion", tiempos, valores);
    }

    function sube(nombre, dur, fn, n = 32) {
      const tiempos = [];
      const valores = [];
      const [x0, y0, z0] = hueso[nombre].position.toArray();
      for (let i = 0; i <= n; i++) {
        tiempos.push(i * (dur / n));
        valores.push(x0, y0 + fn(i / n), z0);
      }
      return new THREE.VectorKeyframeTrack("Hueso" + nombre + ".position", tiempos, valores);
    }

    const sen = (t, c = 1) => Math.sin(t * Math.PI * 2 * c);
    const cos = (t, c = 1) => Math.cos(t * Math.PI * 2 * c);

    // 1. Reposo: flotación marina suave, mecida dulce del cuello robusto y ondulación de aletas
    const dR = 3.2;
    const reposo = new THREE.AnimationClip("Reposo", dR, [
      sube("Cadera", dR, (t) => 0.015 * sen(t)),
      giro("Pecho", dR, (t) => [1.5 * sen(t), 0, 0]),
      giro("Cuello1", dR, (t) => [-2.0 * sen(t), 0, 0]),
      giro("Cuello2", dR, (t) => [1.5 * sen(t), 2.0 * cos(t), 0]),
      giro("Cuello3", dR, (t) => [2.5 * sen(t), 3.0 * cos(t), 0]),
      giro("Cuello4", dR, (t) => [2.0 * sen(t), 3.5 * cos(t), 0]),
      giro("Cabeza", dR, (t) => [-2.0 * sen(t), 2.5 * cos(t), 1.0 * sen(t)]),
      giro("Cola1", dR, (t) => [1.0 * sen(t), 3.0 * sen(t), 0]),
      giro("Cola2", dR, (t) => [1.5 * sen(t), 5.5 * sen(t), 0]),
      giro("Cola3", dR, (t) => [2.0 * sen(t), 8.0 * sen(t), 0]),
      // Aletas flotando y ondulando suavemente como alas
      giro("AletaDelI", dR, (t) => [4 * sen(t), 0, 8 * cos(t)]),
      giro("AletaDelD", dR, (t) => [4 * sen(t), 0, -8 * cos(t)]),
      giro("AletaTrasI", dR, (t) => [-3 * cos(t), 0, 6 * sen(t)]),
      giro("AletaTrasD", dR, (t) => [-3 * cos(t), 0, -6 * sen(t)])
    ]);

    // 2. Caminar / Nadar: vuelo subacuático vigoroso con batido alternado de las 4 hidroalas
    const dC = 2.0;
    const PASO_ALETA = 22;
    const caminar = new THREE.AnimationClip("Caminar", dC, [
      sube("Cadera", dC, (t) => 0.018 * sen(t, 2)),
      giro("Cadera", dC, (t) => [2 * sen(t, 2), 4 * sen(t), 0]),
      giro("Pecho", dC, (t) => [-2 * sen(t, 2), -4 * sen(t), 0]),
      // Ondulación marina armónica del cuello robusto
      giro("Cuello1", dC, (t) => [2 * sen(t, 2), 3 * sen(t), 0]),
      giro("Cuello2", dC, (t) => [-3 * sen(t, 2), -4 * sen(t), 0]),
      giro("Cuello3", dC, (t) => [4 * sen(t, 2), 5 * sen(t), 0]),
      giro("Cuello4", dC, (t) => [-3 * sen(t, 2), -4 * sen(t), 0]),
      giro("Cabeza", dC, (t) => [2 * sen(t, 2), 3 * sen(t), 0]),
      // Cola timón ondulando en contrapunto
      giro("Cola1", dC, (t) => [1 * sen(t, 2), -6 * sen(t), 0]),
      giro("Cola2", dC, (t) => [2 * sen(t, 2), -12 * sen(t), 0]),
      giro("Cola3", dC, (t) => [3 * sen(t, 2), -18 * sen(t), 0]),
      // Batido poderoso de hidroalas pectorales y pélvicas
      giro("AletaDelI", dC, (t) => [PASO_ALETA * sen(t), 0, PASO_ALETA * 0.9 * cos(t)]),
      giro("AletaDelD", dC, (t) => [-PASO_ALETA * sen(t), 0, -PASO_ALETA * 0.9 * cos(t)]),
      giro("AletaTrasI", dC, (t) => [-PASO_ALETA * 0.75 * sen(t), 0, PASO_ALETA * 0.7 * cos(t)]),
      giro("AletaTrasD", dC, (t) => [PASO_ALETA * 0.75 * sen(t), 0, -PASO_ALETA * 0.7 * cos(t)])
    ]);

    // 3. Rugir / Embestida: alza el cuello robusto, abre las fauces mostrando dientes y bate fuerte las aletas
    const dG = 2.0;
    const alzar = [[0, 0], [0.25, 1], [0.75, 1], [1, 0]];
    const abrirBoca = [[0, 0], [0.25, 0], [0.42, 1], [0.72, 1], [0.88, 0], [1, 0]];
    const rugir = new THREE.AnimationClip("Rugir", dG, [
      sube("Cadera", dG, (t) => 0.030 * M.interp(alzar, t)),
      giro("Cadera", dG, (t) => [-6 * M.interp(alzar, t), 0, 0]),
      giro("Pecho", dG, (t) => [-10 * M.interp(alzar, t), 0, 0]),
      giro("Cuello1", dG, (t) => [8 * M.interp(alzar, t), 0, 0]),
      giro("Cuello2", dG, (t) => [-12 * M.interp(alzar, t), 0, 0]),
      giro("Cuello3", dG, (t) => [-10 * M.interp(alzar, t), 0, 0]),
      giro("Cuello4", dG, (t) => [8 * M.interp(alzar, t), 0, 0]),
      giro("Cabeza", dG, (t) => [6 * M.interp(alzar, t), 0, 0]),
      giro("Mandibula", dG, (t) => [28 * M.interp(abrirBoca, t), 0, 0]),
      giro("Cola1", dG, (t) => [4 * M.interp(alzar, t), 8 * sen(t, 2), 0]),
      giro("Cola2", dG, (t) => [6 * M.interp(alzar, t), 16 * sen(t, 2), 0]),
      giro("Cola3", dG, (t) => [8 * M.interp(alzar, t), 24 * sen(t, 2), 0]),
      // Impulso hacia atrás de las aletas para embestir
      giro("AletaDelI", dG, (t) => [22 * M.interp(alzar, t), 0, 16 * M.interp(alzar, t)]),
      giro("AletaDelD", dG, (t) => [22 * M.interp(alzar, t), 0, -16 * M.interp(alzar, t)]),
      giro("AletaTrasI", dG, (t) => [14 * M.interp(alzar, t), 0, 10 * M.interp(alzar, t)]),
      giro("AletaTrasD", dG, (t) => [14 * M.interp(alzar, t), 0, -10 * M.interp(alzar, t)])
    ]);

    g.animations = [reposo, caminar, rugir];
    hueso.Raiz.userData.esqueleto = HUESOS.map(([nombre]) => "Hueso" + nombre);

    return g;
  },

  // Imagen de referencia reducida ×2, sin tinta (RGB en base64) para proyectar colores fieles de futabasaurus_der.webp:
  textura: {
    w: 260, h: 163, k: 2, esc: 0.00240, x0: 260, y0: 325,
    datos: ""
  }
});
